    protected function applyFix(\SplFileInfo $file, Tokens $tokens): void
    {
        $tokenCount = \count($tokens);
        if ($tokenCount < 4) {
            return;
        }

        for ($index = $tokenCount - 3; $index > 0; --$index) {
            if (!$tokens[$index]->isGivenKind(T_DOLLAR_OPEN_CURLY_BRACES)) {
                continue;
            }

            $varnameToken = $tokens[$index + 1];
            if (!$varnameToken->isGivenKind(T_STRING_VARNAME)) {
                continue;
            }

            $varname = $varnameToken->getContent();
            if (!Preg::match('/^[A-Za-z_\x80-\xff][A-Za-z0-9_\x80-\xff]*$/', $varname)) {
                continue;
            }

            $closeIndex = $this->findCloseIndex($tokens, $index + 2);
            if (null === $closeIndex) {
                continue;
            }

            $previousToken = $tokens[$index - 1];
            $previousContent = $previousToken->getContent();
            $previousLength = \strlen($previousContent);
            $rewrittenPrevious = $previousToken;
            if ($previousLength > 0) {
                $lastChar = $previousContent[$previousLength - 1];
                if ('$' === $lastChar) {
                    $endsWithEscapedDollar = false;
                    if ($previousLength > 1) {
                        $beforeLastChar = $previousContent[$previousLength - 2];
                        if ('\\' === $beforeLastChar) {
                            $endsWithEscapedDollar = true;
                        }
                    }

                    if (!$endsWithEscapedDollar) {
                        $escapedContent = substr($previousContent, 0, -1).'\\$';
                        $rewrittenPrevious = new Token([T_ENCAPSED_AND_WHITESPACE, $escapedContent]);
                    }
                }
            }

            $tokens[$index - 1] = $rewrittenPrevious;
            $tokens[$index] = new Token([T_CURLY_OPEN, '{']);
            $tokens[$index + 1] = new Token([T_VARIABLE, '$'.$varname]);
            $tokens[$closeIndex] = new Token([CT::T_CURLY_CLOSE, '}']);
        }
    }

    /**
     * Find the token closing the `${` sequence starting right after it, or null
     * if the content in between is not supported for conversion.
     */
    private function findCloseIndex(Tokens $tokens, int $startIndex): ?int
    {
        $count = \count($tokens);
        $bracketDepth = 0;

        for ($index = $startIndex; $index < $count; ++$index) {
            $token = $tokens[$index];

            if ($bracketDepth > 0) {
                if ($token->equals('[')) {
                    ++$bracketDepth;
                } elseif ($token->equals(']')) {
                    --$bracketDepth;
                } elseif (
                    !$token->isGivenKind([T_CONSTANT_ENCAPSED_STRING, T_LNUMBER, T_VARIABLE, T_NUM_STRING])
                    && !$token->equalsAny(['-', '+'])
                ) {
                    return null;
                }

                continue;
            }

            if ($token->isGivenKind(CT::T_DOLLAR_CLOSE_CURLY_BRACES) || $token->equals('}')) {
                return $index;
            }

            if ($token->equals('[')) {
                ++$bracketDepth;

                continue;
            }

            return null;
        }

        return null;
    }
}

